"""Original sarcoidosis questions: six diagnostic and six pulmonary assessment items."""
from qbank_authoring import question,ref
rows=[]
D=ref('ATS sarcoidosis diagnosis and detection guideline','https://www.thoracic.org/statements/guideline-implementation-tools/diagnosis-and-detection-of-sarcoidosis.php')
T=ref('ERS sarcoidosis treatment guideline: 2021','https://pubmed.ncbi.nlm.nih.gov/34140301/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('Which combination best describes the usual diagnostic framework for sarcoidosis?', 'A compatible clinical/radiological presentation, nonnecrotizing granulomas when tissue is needed, and exclusion of alternative causes',[
 ('An elevated ACE level alone','ACE is neither sufficiently sensitive nor specific to establish the diagnosis.'),('Any granuloma regardless of microbiology or exposure history','Infection, occupational disease, drugs and malignancy-associated reactions can produce granulomas.'),('Bilateral hilar nodes plus mandatory proof of caseating necrosis','Caseation is not the defining sarcoid finding and should raise concern for an alternative process.')],
 'Sarcoidosis is an integrated diagnosis','**No isolated blood test or tissue feature establishes sarcoidosis in every case.**',['Some highly characteristic clinical syndromes can be managed without tissue after a reasoned assessment.','Even a compatible biopsy must be interpreted against infectious and other mimics.'], '**Choose tests that answer the clinical uncertainty.**',['Assess organ involvement and exposure history.','Document why alternatives are adequately excluded before immune treatment.'],[['Clinical pattern','Required context'],['Granulomas','Supportive but not unique'],['Alternatives','Actively evaluate']],[D])

q('A lymph-node biopsy shows nonnecrotizing granulomas in a patient from a TB-endemic region. Which interpretation is appropriate?', 'Tuberculosis and other granulomatous infections still require exclusion before diagnosing sarcoidosis',[
 ('Nonnecrotizing histology definitively excludes TB','TB granulomas are not invariably necrotic in every sample.'),('Negative IGRA alone excludes active TB','IGRA cannot reliably rule out active disease.'),('Granulomas prove that culture and organism-directed testing are unnecessary','Microbiological evaluation may be essential.')],
 'Granuloma morphology does not uniquely identify the cause','**TB, fungal infection and other conditions can mimic sarcoidosis.**',['Use exposure, symptoms, imaging, stains, molecular tests and cultures as appropriate.','Prior treatment and specimen handling influence diagnostic yield.'], '**Preserve suitable tissue for microbiology when infection is possible.**',['Do not place the entire sample in formalin if fresh material is needed.','Avoid unsafe immune escalation from the histology label alone.'],[['Nonnecrotizing granuloma','Not uniquely sarcoid'],['IGRA','Not an active-TB exclusion test'],['Microbiology','Context-directed tissue testing']],[D],style='clinical_scenario')

q('A patient needs tissue confirmation of suspected thoracic sarcoidosis and has accessible mediastinal/hilar adenopathy. Which initial approach is generally favored over mediastinoscopy?', 'EBUS-guided nodal sampling',[
 ('Open surgical lung biopsy in every case','A less invasive informative target is usually preferred when available.'),('Random endomyocardial biopsy despite no cardiac syndrome','This is not the appropriate first target for this presentation.'),('Splenectomy solely to obtain a diagnosis','This is unnecessarily invasive when a thoracic nodal target is available.')],
 'Choose the least invasive informative tissue target','**ATS favors EBUS-guided sampling when thoracic nodes require sampling.**',['A skin or peripheral node lesion can be an even simpler target in selected patients.','Specimens should also assess alternative diagnoses such as infection and lymphoma when indicated.'], '**Balance diagnostic yield, procedure risk and the differential.**',['Some characteristic presentations do not require biopsy.','A nondiagnostic sample may require a different method if uncertainty remains important.'],[['EBUS','Less invasive nodal approach'],['Peripheral lesion','May be an easier target'],['Surgery','Selected unresolved cases']],[D],style='clinical_scenario')

q('Bilateral hilar adenopathy, erythema nodosum and acute ankle periarthritis in a young adult most strongly suggest which syndrome?', 'Lofgren syndrome',[
 ('Heerfordt syndrome','This more characteristically includes parotid swelling, uveitis and facial palsy.'),('Felty syndrome','This is an RA-associated neutropenic syndrome.'),('Antisynthetase syndrome','The myositis/ILD/arthritis/mechanic’s-hand phenotype is different.')],
 'Recognize a characteristic acute sarcoid presentation','**Lofgren syndrome is a highly suggestive clinical constellation.**',['Ankle swelling can include prominent periarticular inflammation.','The clinical context and exclusion of relevant mimics still matter.'], '**Assess symptoms and organ involvement before deciding on biopsy or systemic treatment.**',['Many cases have a favorable course.','Erythema nodosum itself is a reactive panniculitis and is not the best target for demonstrating sarcoid granulomas.'],[['Lofgren','BHL + erythema nodosum + ankle inflammation'],['Heerfordt','Parotid/uveal/facial nerve pattern'],['Course','Often favorable, but assess organs']],[D],style='clinical_scenario')

q('A metal-machining worker has granulomatous lung disease and thoracic adenopathy resembling sarcoidosis. Which exposure-related diagnosis is particularly important?', 'Chronic beryllium disease',[
 ('Silicosis as the only possible occupational granulomatous disorder','Silica disease is a differential, but beryllium can closely mimic the sarcoid granulomatous phenotype.'),('Asbestosis','Its fibrotic/pleural exposure phenotype is different.'),('Byssinosis','This is associated with cotton dust-related airway symptoms rather than the classic granulomatous mimic.')],
 'Take an occupational history before calling a granuloma idiopathic','**Beryllium sensitization and disease can closely resemble sarcoidosis.**',['A beryllium lymphocyte proliferation test supports exposure-specific assessment.','Exposure can be remote or unrecognized without detailed job history.'], '**Coordinate occupational evaluation when indicated.**',['Review workplace tasks and materials, not only the job title.','Avoid using a nonspecific ACE elevation to dismiss an occupational explanation.'],[['Beryllium','Sarcoid-like granulomatous mimic'],['BeLPT','Exposure-specific immune test'],['History','Can reveal an overlooked cause']],[D],style='clinical_scenario')

q('Which statement about serum ACE in sarcoidosis is correct?', 'It can support context in selected patients but cannot independently confirm disease, exclude disease or determine treatment',[
 ('A normal ACE excludes sarcoidosis','Sensitivity is inadequate for that use.'),('An elevated ACE proves sarcoidosis regardless of the differential','Other conditions can raise ACE.'),('ACE normalization alone proves that all organ injury has resolved','Clinical and organ-specific assessment remain necessary.')],
 'Do not overinterpret a granuloma-associated biomarker','**ACE is an imperfect supporting marker.**',['Genetics, medications and disease phenotype affect the result.','Its trend may be informative in a patient whose disease tracks it, but is not a universal target.'], '**Base decisions on organ risk, symptoms and objective disease.**',['Use kidney, calcium, eye, cardiac and lung assessment as appropriate.','Do not start systemic treatment solely for a high ACE level.'],[['High ACE','Not uniquely diagnostic'],['Normal ACE','Does not exclude'],['Treatment','Organ- and symptom-directed']],[D,T])

q('A chest radiograph shows bilateral hilar adenopathy with parenchymal infiltrates in sarcoidosis. Which traditional radiographic stage is this?', 'Stage II',[
 ('Stage I','This denotes hilar adenopathy without parenchymal infiltrates.'),('Stage III','This denotes parenchymal infiltrates without hilar adenopathy.'),('Stage IV','This denotes established pulmonary fibrosis.')],
 'Use Scadding stages descriptively','**Stage II combines hilar adenopathy and parenchymal disease.**',['The stages are not a mandatory sequential progression.','They do not alone define current physiological impairment or treatment need.'], '**Assess function and organ threat separately.**',['Symptoms, PFT trajectory and HRCT add information beyond the plain film.','Do not assume every stage II patient needs the same systemic regimen.'],[['I','Nodes only'],['II','Nodes plus infiltrates'],['III/IV','Infiltrates without nodes/fibrosis']],[D,T],style='clinical_scenario')

q('Which HRCT distribution is particularly characteristic of pulmonary sarcoidosis?', 'Perilymphatic micronodules along bronchovascular bundles, fissures and subpleural surfaces',[
 ('Uniform random miliary nodules as the only typical pattern','A random pattern raises other differentials including disseminated infection or hematogenous disease.'),('Basal peripheral honeycombing without any other features as uniquely diagnostic','This is not specific and can suggest other fibrotic disorders.'),('An isolated dependent lobar consolidation as the defining pattern','This more often raises focal infection or aspiration among other causes.')],
 'Use the nodule distribution to refine the differential','**Perilymphatic nodules reflect granulomatous involvement along pulmonary lymphatic routes.**',['Upper/mid-lung predominance and thoracic nodes can support the pattern.','No CT appearance alone excludes infection or malignancy in every context.'], '**Integrate imaging with exposures, symptoms and tissue when needed.**',['Atypical unilateral, necrotic or mass-like findings deserve reassessment.','Fibrotic disease can distort the usual pattern.'],[['Perilymphatic','Sarcoid-supporting distribution'],['Random','Hematogenous differential'],['Airway-centric','Different exposure/infectious possibilities']],[D])

q('Which statement about pulmonary function in sarcoidosis is correct?', 'Restriction, obstruction, mixed defects or normal spirometry can occur; DLCO and serial change add important information',[
 ('Every patient has a purely restrictive defect','Airway involvement can produce obstruction and some patients have normal testing.'),('Normal spirometry excludes all pulmonary vascular disease','DLCO and other assessment can reveal a different mechanism.'),('One FVC value determines treatment for all patients regardless of trend or symptoms','Trajectory and organ context are essential.')],
 'Do not reduce lung assessment to one expected pattern','**Sarcoidosis can involve parenchyma, airways and pulmonary vessels.**',['PFTs quantify impact but do not independently identify every mechanism.','A disproportionate DLCO reduction warrants assessment for vascular or other contributors.'], '**Follow a consistent longitudinal assessment.**',['Combine symptoms, FVC/DLCO, oxygenation and imaging as needed.','Investigate a change rather than assume it is always inflammatory relapse.'],[['FVC','Volume/functional trend'],['DLCO','Gas-transfer impact'],['Pattern','Can be restrictive, obstructive or mixed']],[D,T])

q('A patient with sarcoidosis has dyspnea out of proportion to parenchymal CT findings, falling DLCO and exertional syncope. Which complication should be assessed?', 'Sarcoidosis-associated pulmonary hypertension',[
 ('Simple deconditioning as certain without further testing','Syncope and disproportionate physiological changes are warning features.'),('Isolated erythema nodosum','This does not explain the pulmonary vascular syndrome.'),('Uncomplicated reflux as the complete explanation','This does not account for syncope and gas-transfer changes.')],
 'Pulmonary hypertension can have several sarcoid mechanisms','**Vascular involvement, fibrosis, hypoxemia, extrinsic compression and cardiac disease can contribute.**',['Echocardiography estimates probability.','Right-heart catheterization confirms and characterizes PH when indicated.'], '**Define the mechanism before selecting treatment.**',['Specialist care is important because PAH drugs are not automatically appropriate for every mechanism.','Assess oxygen need, cardiac function and advanced-disease referral.'],[['Disproportionate dyspnea','Consider PH'],['Echo','Initial probability assessment'],['RHC','Hemodynamic confirmation']],[D,ref('WASOG sarcoidosis-associated PH statement','https://doi.org/10.1183/16000617.0165-2021')],style='clinical_scenario')

q('A patient with fibrotic pulmonary sarcoidosis and an upper-lobe cavity develops recurrent hemoptysis. CT shows an intracavitary mass with surrounding air. Which complication is most likely?', 'Aspergilloma/chronic Aspergillus-related cavity disease',[
 ('An ordinary uncomplicated sarcoid flare as certain','The cavitary mass and hemoptysis suggest a superimposed complication.'),('Acute pulmonary edema','This does not explain the intracavitary fungal-ball pattern.'),('Isolated pleural effusion','This is a different anatomical finding.')],
 'Damaged lung can acquire a second disease','**Sarcoid cavities can be colonized or infected by Aspergillus.**',['Hemoptysis may be severe and needs assessment of stability.','Chronic pulmonary aspergillosis and a simple fungal ball have different management implications.'], '**Investigate before escalating immunosuppression.**',['Obtain appropriate imaging, serology and microbiological assessment.','Major bleeding can require urgent bronchial artery or surgical evaluation.'],[['Cavity plus mass','Aspergillus complication'],['Hemoptysis','Can be dangerous'],['Immune escalation','May worsen an unrecognized infection']],[T,ref('IDSA aspergillosis guideline','https://www.idsociety.org/practice-guideline/aspergillosis/')],style='clinical_scenario')

q('A PET scan shows intense FDG uptake in mediastinal nodes in a patient with suspected sarcoidosis. Which interpretation is correct?', 'The uptake identifies metabolically active tissue but does not distinguish sarcoidosis reliably from infection or malignancy',[
 ('High SUV proves lymphoma in every case','Inflammatory granulomatous lesions can also have high uptake.'),('High SUV proves sarcoidosis in every case','Malignancy and infection can produce the same signal.'),('PET makes tissue unnecessary in every atypical presentation','A diagnostic biopsy can still be essential.')],
 'Activity imaging is not an etiological fingerprint','**FDG uptake is nonspecific.**',['PET can help locate an informative biopsy target or assess selected disease activity.','Clinical probability and the differential determine what the scan means.'], '**Use the scan to answer a defined question.**',['Sample an accessible informative lesion when tissue is needed.','Do not diagnose relapse or cancer solely from an uptake threshold.'],[['FDG uptake','Metabolic activity'],['Etiology','Requires clinical/tissue context'],['Biopsy targeting','Potential useful role']],[D],style='clinical_scenario')

if __name__=='__main__':print(f'Sarcoidosis draft: {len(rows)} questions')
